package vn.hust.restaurant.view;
import java.awt.*;import java.time.*;import java.util.*;import javax.swing.*;import javax.swing.table.*;import vn.hust.restaurant.config.AppContext;import vn.hust.restaurant.model.*;
public class ReservationPanel extends JPanel implements Refreshable{private final AppContext ctx;private final UserSession session;private final DefaultTableModel model=Ui.model("ID","Bàn","Tên khách","SĐT","Thời gian","Số người","Trạng thái","Ghi chú");private final JTable table=new JTable(model);private java.util.List<Reservation>data=java.util.List.of();public ReservationPanel(AppContext c,UserSession s){ctx=c;session=s;setLayout(new BorderLayout());JButton add=new JButton("Đặt bàn"),cancel=new JButton("Hủy đặt"),reload=new JButton("Làm mới");add(Ui.toolbar(add,cancel,reload),BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);add.addActionListener(e->create());cancel.addActionListener(e->{int r=table.getSelectedRow();if(r>=0&&Ui.confirm(this,"Hủy lịch đặt này?"))Ui.run(this,()->{ctx.reservations.cancel(data.get(r).id());refresh();});});reload.addActionListener(e->refresh());refresh();}
 public void refresh(){Ui.run(this,()->{data=ctx.reservations.upcoming();model.setRowCount(0);for(Reservation x:data)model.addRow(new Object[]{x.id(),x.tableCode(),x.guestName(),x.phone(),Ui.DT.format(x.reservedAt()),x.partySize(),x.status(),x.note()});});}
 private void create(){Ui.run(this,()->{java.util.List<DiningTable>tables=ctx.tables.all().stream().filter(x->"TRONG".equals(x.status())).toList();if(tables.isEmpty())throw new IllegalArgumentException("Không có bàn trống");JComboBox<DiningTable>tb=new JComboBox<>(tables.toArray(DiningTable[]::new));JTextField name=Ui.field("",18),phone=Ui.field("",14),at=Ui.field(Ui.DT.format(LocalDateTime.now().plusHours(2)),16),party=Ui.field("2",5),note=Ui.field("",20);Object[]f={"Bàn",tb,"Tên người đặt",name,"SĐT",phone,"Thời gian (yyyy-MM-dd HH:mm)",at,"Số người",party,"Ghi chú",note};if(JOptionPane.showConfirmDialog(this,f,"Đặt bàn",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){DiningTable t=(DiningTable)tb.getSelectedItem();ctx.reservations.create(t.id(),null,session.employeeId(),name.getText(),phone.getText(),Ui.dateTime(at.getText()),Ui.integer(party.getText()),note.getText());refresh();}});}}
